const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Skip non-result items (html_attributions etc)
  if (!data.result) continue;

  const live = data.result;

  // Find matching restaurant from loop node
  const loop = $('🔄 Loop Over Restaurants').all().find(i => 
    i.json.place_id === data.result.place_id || 
    i.json.name === data.result.name
  );

  if (!loop) continue;

  const stored = loop.json;
  const r = parseFloat(stored.last_rating) || 4.0;
  const rc = parseInt(stored.last_review_count) || 0;
  const rd = parseFloat((live.rating - r).toFixed(2));
  const rvd = live.user_ratings_total - rc;

  // Determine alert level
  let al = 'none';
  if (rd <= -0.3) al = 'critical';
  else if (rd <= -0.1 || rvd > 50) al = 'watch';
  else if (rd >= 0.2) al = 'positive';

  // Extract review text for AI
  const rv = (live.reviews || []).map(x => x.rating + 'star ' + x.text).join(' | ');

  results.push({
    json: {
      place_id: stored.place_id,
      name: live.name,
      result: live,
      last_rating: r,
      last_review_count: rc,
      ratingDiff: rd,
      reviewDiff: rvd,
      alertLevel: al,
      reviewsText: rv,
      checkedAt: new Date().toISOString()
    }
  });
}

return results;

